<?php
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$st=$pdo->prepare("SELECT s.*,c.name customer,u.name seller,COALESCE(r.ret,0) returned FROM sales s LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.user_id LEFT JOIN (SELECT sale_id,SUM(total) ret FROM sale_returns GROUP BY sale_id) r ON r.sale_id=s.id WHERE DATE(s.created_at) BETWEEN ? AND ? ORDER BY s.id DESC");$st->execute([$from,$to]);$rows=$st->fetchAll();$sum=0;foreach($rows as $r)if(!in_array($r['status'],['cancelled','returned'],true))$sum+=max(0,$r['total']-$r['returned']);$title='Vendas';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Vendas</h1><p>Cupons, status, pagamentos e pós-venda.</p></div><?php if(can('pos')):?><a class="btn primary" href="index.php?page=pos">+ Nova venda</a><?php endif;?></div><section class="panel"><form class="filters"><label>De<input type="date" name="from" value="<?=e($from)?>"></label><label>Até<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn">Filtrar</button><strong>Líquido: <?=money($sum)?></strong></form><div class="table-wrap"><table><thead><tr><th>Venda</th><th>Cliente</th><th>Vendedor</th><th>Pagamento</th><th>Status</th><th>Total</th><th>Data</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="index.php?page=sale_view&id=<?=$r['id']?>">#<?=$r['id']?></a></td><td><?=e($r['customer']?:'Consumidor final')?></td><td><?=e($r['seller'])?></td><td><?=e(paymentLabel($r['payment_method']))?></td><td><span class="badge <?=$r['status']==='completed'?'ok':'danger'?>"><?=e($r['status'])?></span></td><td><?=money(max(0,$r['total']-$r['returned']))?></td><td><?=date('d/m/Y H:i',strtotime($r['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../../includes/footer.php';?>
